from itertools import permutations

def sign(p):
    # p is a tuple representing the permutation (p[0] is image of 1, p[1] of 2, etc.)
    # We calculate the number of inversions
    inversions = 0
    n = len(p)
    for i in range(n):
        for j in range(i + 1, n):
            if p[i] > p[j]:
                inversions += 1
    return 1 if inversions % 2 == 0 else -1

def fixed_points(p):
    # p is a tuple where p[i-1] is the image of i.
    # Check if pi(i) = i, which means p[i-1] = i
    return sum(1 for i in range(len(p)) if p[i] == i + 1)

N = 3
S_N = list(permutations(range(1, N + 1)))
A_N = 0

for p in S_N:
    s_pi = sign(p)
    v_pi = fixed_points(p)
    A_N += s_pi / (v_pi + 1)

print(f"N={N}, A_N = {A_N}")

